"use strict";(globalThis.webpackChunktrizlink_docs=globalThis.webpackChunktrizlink_docs||[]).push([[1567],{5226(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"mainSidebar":[{"type":"link","href":"/intro","label":"Introduction to Trizlink","docId":"intro","unlisted":false},{"type":"category","label":"Getting Started","collapsed":false,"items":[{"type":"link","href":"/getting-started/create-account","label":"Create your account","docId":"getting-started/create-account","unlisted":false},{"type":"link","href":"/getting-started/quick-start","label":"Quick start","docId":"getting-started/quick-start","unlisted":false}],"collapsible":true},{"type":"category","label":"Features","collapsed":false,"items":[{"type":"link","href":"/features/short-links","label":"Short links","docId":"features/short-links","unlisted":false},{"type":"link","href":"/features/link-in-bio","label":"Bio pages","docId":"features/link-in-bio","unlisted":false},{"type":"link","href":"/features/qr-codes","label":"QR codes","docId":"features/qr-codes","unlisted":false},{"type":"link","href":"/features/analytics","label":"Analytics","docId":"features/analytics","unlisted":false},{"type":"link","href":"/features/custom-domains","label":"Custom domains","docId":"features/custom-domains","unlisted":false},{"type":"link","href":"/features/link-organization","label":"Link organisation","docId":"features/link-organization","unlisted":false},{"type":"link","href":"/features/tracking-and-utm","label":"Tracking and UTM","docId":"features/tracking-and-utm","unlisted":false},{"type":"link","href":"/features/workspaces-and-teams","label":"Workspaces and teams","docId":"features/workspaces-and-teams","unlisted":false},{"type":"link","href":"/features/social-media","label":"Social publishing","docId":"features/social-media","unlisted":false},{"type":"link","href":"/features/widgets","label":"Widgets","docId":"features/widgets","unlisted":false},{"type":"link","href":"/features/ai-features-byok","label":"AI assistance","docId":"features/ai-features-byok","unlisted":false},{"type":"link","href":"/features/ai-levels-and-voice","label":"AI levels and voice","docId":"features/ai-levels-and-voice","unlisted":false},{"type":"link","href":"/features/api-access","label":"Public API","docId":"features/api-access","unlisted":false},{"type":"link","href":"/features/utility-tools","label":"Utility tools","docId":"features/utility-tools","unlisted":false},{"type":"link","href":"/features/browser-extension","label":"Browser extension","docId":"features/browser-extension","unlisted":false},{"type":"link","href":"/features/theme-customizer","label":"Theme control","docId":"features/theme-customizer","unlisted":false},{"type":"link","href":"/features/sharing","label":"Sharing a link","docId":"features/sharing","unlisted":false},{"type":"link","href":"/features/page-tours-and-walkthrough","label":"Page tours and the product walkthrough","docId":"features/page-tours-and-walkthrough","unlisted":false},{"type":"link","href":"/features/referrals","label":"Referrals","docId":"features/referrals","unlisted":false}],"collapsible":true},{"type":"category","label":"Guides","collapsed":true,"items":[{"type":"link","href":"/guides/faq","label":"Frequently asked questions","docId":"guides/faq","unlisted":false}],"collapsible":true},{"type":"category","label":"About","collapsed":true,"items":[{"type":"link","href":"/about/privacy-and-data","label":"Privacy and data","docId":"about/privacy-and-data","unlisted":false},{"type":"link","href":"/about/changelog","label":"Changelog","docId":"about/changelog","unlisted":false},{"type":"link","href":"/about/about-the-author","label":"About the Trizlink team","docId":"about/about-the-author","unlisted":false}],"collapsible":true}]},"docs":{"about/about-the-author":{"id":"about/about-the-author","title":"About the Trizlink team","description":"Trizlink is built and maintained by the Trizlink team. Product questions go to the contact page on trizlink.com, or to support@trizlink.com.","sidebar":"mainSidebar"},"about/changelog":{"id":"about/changelog","title":"Changelog","description":"Notable changes to Trizlink and to this documentation site, latest first. Version 2.13.0 rebuilt the product on a new database and did not carry old data across.","sidebar":"mainSidebar"},"about/privacy-and-data":{"id":"about/privacy-and-data","title":"Privacy and data","description":"What Trizlink stores, what it deliberately does not store, and why no visitor IP address exists in the database. A plain summary alongside the legal text.","sidebar":"mainSidebar"},"features/ai-features-byok":{"id":"features/ai-features-byok","title":"AI assistance","description":"Trizlink\'s AI runs on our credit at your plan\'s level, with monthly AI and voice allowances on every plan; your own Anthropic or OpenAI key lifts both, Free included.","sidebar":"mainSidebar"},"features/ai-levels-and-voice":{"id":"features/ai-levels-and-voice","title":"AI levels and voice","description":"Every Trizlink plan includes AI at one of three levels, Spark, Pulse or Surge, with monthly AI and voice allowances. Your own Anthropic or OpenAI key lifts both.","sidebar":"mainSidebar"},"features/analytics":{"id":"features/analytics","title":"Analytics","description":"Trizlink records one row per click with country, device, referrer and browser, stores no visitor IP address, and reports refused visits alongside successful ones.","sidebar":"mainSidebar"},"features/api-access":{"id":"features/api-access","title":"Public API","description":"Eighteen REST endpoints at api.trizlink.com/v1 for links, bio pages, analytics, domains, webhooks and social posts, with per-resource scopes and separate destructive permissions.","sidebar":"mainSidebar"},"features/browser-extension":{"id":"features/browser-extension","title":"Browser extension","description":"Trizlink does not offer a browser extension. Here is why, what to use instead to shorten a link quickly, and what would have to be true for one to ship.","sidebar":"mainSidebar"},"features/custom-domains":{"id":"features/custom-domains","title":"Custom domains","description":"Add a domain you own to Trizlink and prove it with three DNS records. Verification works today; serving short links on a verified domain is not live yet.","sidebar":"mainSidebar"},"features/link-in-bio":{"id":"features/link-in-bio","title":"Bio pages","description":"A Trizlink bio page is one public address holding every link you would otherwise have to choose between, built from fifteen block types on three layouts, with drafts, passwords and view counts.","sidebar":"mainSidebar"},"features/link-organization":{"id":"features/link-organization","title":"Link organisation","description":"Folders, labels and collections are three different structures in Trizlink, not three names for one. Plus CSV import of up to 5,000 rows, parsed in your browser.","sidebar":"mainSidebar"},"features/page-tours-and-walkthrough":{"id":"features/page-tours-and-walkthrough","title":"Page tours and the product walkthrough","description":"Press Tour this page for a short guided tour of the page you are on. The product walkthrough shows how Trizlink works, one real screen per step.","sidebar":"mainSidebar"},"features/qr-codes":{"id":"features/qr-codes","title":"QR codes","description":"Every Trizlink short link can be drawn as a QR code, derived from the address each time rather than stored, with four error-correction levels and optional separate scan counting.","sidebar":"mainSidebar"},"features/referrals":{"id":"features/referrals","title":"Referrals","description":"Invite someone to Trizlink and earn points and a dated badge on every confirmed referral, plus a month of a paid plan once you reach the threshold, with every number set in the admin panel rather than fixed in the product.","sidebar":"mainSidebar"},"features/sharing":{"id":"features/sharing","title":"Sharing a link","description":"One copy control with an honest fallback, and a per-link social card you control. Trizlink has no share modal and no native share sheet, and this page says so.","sidebar":"mainSidebar"},"features/short-links":{"id":"features/short-links","title":"Short links","description":"A Trizlink short link is a short address that resolves to a destination you can change, with optional passwords, expiry, click ceilings, geo and device targeting and A/B splits.","sidebar":"mainSidebar"},"features/social-media":{"id":"features/social-media","title":"Social publishing","description":"Compose one post, preview it per network and queue it per account. Trizlink\'s social publishing is built and currently publishes nothing, and this page says why.","sidebar":"mainSidebar"},"features/theme-customizer":{"id":"features/theme-customizer","title":"Theme control","description":"One panel, nine appearance axes, applied before the first paint from a single registry. Preferences are held on the device rather than synced to your account.","sidebar":"mainSidebar"},"features/tracking-and-utm":{"id":"features/tracking-and-utm","title":"Tracking and UTM","description":"Attach tracking pixels to Trizlink links, save UTM templates, receive webhooks on ten link and workspace events, and record conversions with a beacon that stores no visitor address.","sidebar":"mainSidebar"},"features/utility-tools":{"id":"features/utility-tools","title":"Utility tools","description":"A curated directory of 48 free browser tools hosted on ZTools, a separate product. Trizlink\'s own tools suite was retired in July 2026 and the directory replaced it.","sidebar":"mainSidebar"},"features/widgets":{"id":"features/widgets","title":"Widgets","description":"Embed a Trizlink link, bio page or collection on any site in four shapes \u2014 inline, button, popup or QR \u2014 with a snippet generated from the widget rather than stored.","sidebar":"mainSidebar"},"features/workspaces-and-teams":{"id":"features/workspaces-and-teams","title":"Workspaces and teams","description":"A Trizlink workspace is the tenant that owns links, bio pages and analytics. Four roles and seven capabilities on every plan; teams and the audit log on Team.","sidebar":"mainSidebar"},"getting-started/create-account":{"id":"getting-started/create-account","title":"Create your account","description":"Sign in to Trizlink with your Google account, meet the workspace created for you, and learn how deletion, the 30-day window and the rebuild data reset work before you start.","sidebar":"mainSidebar"},"getting-started/quick-start":{"id":"getting-started/quick-start","title":"Quick start","description":"Create your first Trizlink short link, draw its QR code, publish a bio page and read the click breakdowns, with the limits of each step stated as you go.","sidebar":"mainSidebar"},"guides/faq":{"id":"guides/faq","title":"Frequently asked questions","description":"Short answers to what people actually ask about Trizlink \u2014 plans, sign-in, custom domains, the missing browser extension, AI metering, the API and what happened to old links.","sidebar":"mainSidebar"},"intro":{"id":"intro","title":"Introduction to Trizlink","description":"Trizlink runs short links, bio pages and social posts out of one workspace, with a single analytics layer across all three. What it does, what it does not, and where the limits are.","sidebar":"mainSidebar"}}}}')}}]);